dtsPropsFor.MovementRow:
movement: {
  id: string;
  type: "DEPOSIT" | "TRANSFER_IN" | "TRANSFER_OUT" | "OWN_TRANSFER_IN" | "OWN_TRANSFER_OUT";
  /** Monto con signo y 2 decimales, como string: "-1500.00" (salida), "25000.00" (entrada). */
  amount: string;
  /** Saldo de la cuenta después del movimiento, "23500.00". */
  balanceAfter: string;
  concept: string;
  reference: string;
  /** null en los DEPOSIT de la Tesorería. */
  counterparty: { name: string; clabeLast4: string } | null;
  transferId: string;
  /** ISO 8601; se muestra en hora de Ciudad de México. */
  occurredAt: string;
};

dtsPropsFor.Receipt:
/** Transferencia tal como la devolvió la API. */
transfer: {
  id: string;
  status: "PENDING_OTP" | "COMPLETED" | "REJECTED" | "FAILED" | "EXPIRED";
  kind: "OWN" | "THIRD_PARTY";
  fromAccountId: string;
  destination: {
    type: "OWN_ACCOUNT" | "BENEFICIARY";
    accountId: string | null;
    beneficiaryId: string | null;
    displayName: string;
    clabeLast4: string;
  };
  /** Monto en pesos como string con 2 decimales, "5000.00". */
  amount: string;
  concept: string;
  reference: string;
  requiresOtp: boolean;
  otp: {
    channel: "EMAIL";
    deliveryStatus: "SENT" | "FAILED";
    maskedDestination: string;
    expiresAt: string;
    attemptsRemaining: number;
    resendsRemaining: number;
  } | null;
  rejectionReason: "INSUFFICIENT_FUNDS" | "DAILY_LIMIT_EXCEEDED" | null;
  failureReason: "INSUFFICIENT_FUNDS" | "DAILY_LIMIT_EXCEEDED" | "OTP_ATTEMPTS_EXHAUSTED" | null;
  createdAt: string;
  completedAt: string | null;
};
/** Nombre de la cuenta de origen; sin él muestra "Tu cuenta". */
fromAccountName?: string;
